import { useState, FormEvent } from 'react';
import {
  JxForm,
  JxFormField,
  JxLabel,
  JxInput,
  JxSelect,
  JxSelectOption,
  JxSwitch,
  JxButton,
  JxStack,
} from '@jinx-ui/react';

type Language = 'ru' | 'en';

interface ProfileSettings {
  name: string;
  language: Language;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  initialSettings?: ProfileSettings;
  onSave: (settings: ProfileSettings) => void;
}

const defaultSettings: ProfileSettings = {
  name: '',
  language: 'ru',
  emailNotifications: true,
};

export default function ProfileSettingsForm({
  initialSettings = defaultSettings,
  onSave,
}: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialSettings.name);
  const [language, setLanguage] = useState<Language>(initialSettings.language);
  const [emailNotifications, setEmailNotifications] = useState(
    initialSettings.emailNotifications
  );

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name, language, emailNotifications });
  };

  return (
    <JxForm className="jx-p-6" onSubmit={handleSubmit}>
      <JxStack direction="column" gap="var(--jx-space-4)">
        <JxFormField>
          <JxLabel htmlFor="profile-name">Имя</JxLabel>
          <JxInput
            id="profile-name"
            name="name"
            value={name}
            onChange={(event) => setName(event.target.value)}
            placeholder="Введите имя"
          />
        </JxFormField>

        <JxFormField>
          <JxLabel htmlFor="profile-language">Язык интерфейса</JxLabel>
          <JxSelect
            id="profile-language"
            name="language"
            value={language}
            onValueChange={(value) => setLanguage(value as Language)}
          >
            <JxSelectOption value="ru">Русский</JxSelectOption>
            <JxSelectOption value="en">Английский</JxSelectOption>
          </JxSelect>
        </JxFormField>

        <JxFormField>
          <JxStack direction="row" align="center" justify="space-between">
            <JxLabel htmlFor="profile-email-notifications">
              Уведомления на почту
            </JxLabel>
            <JxSwitch
              id="profile-email-notifications"
              name="emailNotifications"
              checked={emailNotifications}
              onCheckedChange={setEmailNotifications}
            />
          </JxStack>
        </JxFormField>

        <JxButton type="submit" variant="primary">
          Сохранить
        </JxButton>
      </JxStack>
    </JxForm>
  );
}

